import {validPolygon} from './geo.mjs';
import {parseMeters} from './buildings.mjs';
export const sourceSize=v=>{const n=parseMeters(v);return n>0?n:null;};
// Fallbacks are user-controlled illustrative dimensions, not measured averages.
export function treeDimensions(tags={},treeHeight=6,treeCrown=3){const h=sourceSize(tags.height),d=sourceSize(tags.diameter_crown);return {h:h??sourceSize(treeHeight)??6,d:d??sourceSize(treeCrown)??3,estimated:h===null||d===null};}
export function clipSegment(a,b,s){let lo=0,hi=1;const d=[b[0]-a[0],b[1]-a[1]];for(let i=0;i<2;i++){if(!d[i]){if(a[i]<0||a[i]>s)return null;continue;}let u=-a[i]/d[i],v=(s-a[i])/d[i];if(u>v)[u,v]=[v,u];lo=Math.max(lo,u);hi=Math.min(hi,v);if(lo>hi)return null;}return [a.map((v,i)=>v+d[i]*lo),a.map((v,i)=>v+d[i]*hi)];}
export function sampledSegment(a,b,step=5){const n=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/step));return Array.from({length:n+1},(_,i)=>a.map((v,j)=>v+(b[j]-v)*i/n));}

// Triangle ribbons sampled along and across the path. Bounds clamp only clips edges.
export function ribbonVertices(coords,width,side,elevation,curbHeight=0){const out=[];if(!Number.isFinite(width)||width<=0)return out;const height=Number.isFinite(curbHeight)?Math.max(0,Math.min(.5,curbHeight)):0,clamp=v=>Math.max(0,Math.min(side,v)),quad=(a,b,c,d)=>out.push(...a,...b,...c,...a,...c,...d);for(let i=1;i<coords.length;i++){const seg=clipSegment(coords[i-1],coords[i],side);if(!seg)continue;const [a,b]=seg,dx=b[0]-a[0],dy=b[1]-a[1],length=Math.hypot(dx,dy);if(length<1e-6)continue;const nx=-dy/length,ny=dx/length,along=Math.ceil(length/2),across=Math.max(1,Math.ceil(width/2));const vertex=(u,v,level=height)=>{const x=clamp(a[0]+dx*u+nx*width*(v-.5)),y=clamp(a[1]+dy*u+ny*width*(v-.5));return [x-side/2,elevation(x,y)+.02+level,side/2-y];};for(let j=0;j<along;j++)for(let k=0;k<across;k++){const u=j/along,v=k/across,U=(j+1)/along,V=(k+1)/across,A=vertex(u,v),B=vertex(U,v),C=vertex(U,V),D=vertex(u,V);quad(A,B,C,D);if(height>0){const a0=vertex(u,v,0),b0=vertex(U,v,0),c0=vertex(U,V,0),d0=vertex(u,V,0);quad(d0,c0,b0,a0);if(k===0)quad(a0,b0,B,A);if(k===across-1)quad(c0,d0,D,C);if(j===0)quad(d0,a0,A,D);if(j===along-1)quad(b0,c0,C,B);}}}return out;}

export function exactRibbonVertices(coords,width,side,drapePolygon,drapePolyline,curbHeight=0){const result=[],height=Number.isFinite(curbHeight)?Math.max(0,Math.min(.5,curbHeight)):0;if(!(width>0&&Number.isFinite(width)))return result;for(let i=1;i<coords.length;i++){const c=clipSegment(coords[i-1],coords[i],side);if(!c)continue;const [a,b]=c,dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy);if(len<1e-6)continue;const n=[-dy/len*width/2,dx/len*width/2];let ring=[[a[0]+n[0],a[1]+n[1]],[b[0]+n[0],b[1]+n[1]],[b[0]-n[0],b[1]-n[1]],[a[0]-n[0],a[1]-n[1]]];for(const [axis,bound,sign] of [[0,0,1],[0,side,-1],[1,0,1],[1,side,-1]]){const next=[];for(let k=0;k<ring.length;k++){const A=ring[k],B=ring[(k+1)%ring.length],insideA=(A[axis]-bound)*sign>=0,insideB=(B[axis]-bound)*sign>=0;if(insideA)next.push(A);if(insideA!==insideB){const t=(bound-A[axis])/(B[axis]-A[axis]);next.push(A.map((v,j)=>v+(B[j]-v)*t));}}ring=next;}if(ring.length<3)continue;ring.push(ring[0]);const top=drapePolygon([ring],.03+height);for(const v of top)result.push(v);if(height>0){const bottom=drapePolygon([ring],.03);for(let k=0;k<bottom.length;k+=9)result.push(...bottom.slice(k+6,k+9),...bottom.slice(k+3,k+6),...bottom.slice(k,k+3));const edge=drapePolyline(ring,.03);for(let k=1;k<edge.length;k++){const A=edge[k-1],B=edge[k],C=[B[0],B[1]+height,B[2]],D=[A[0],A[1]+height,A[2]];result.push(...A,...B,...C,...A,...C,...D);}}}return result;}
export function addLandscape(T,scene,features,{xy,elevation,side,treeHeight=6,treeCrown=3,pathWidth=2,roadWidth=6,curbHeight=.15,drapePolygon,drapePolyline,layers={paths:true,trees:true,objects:true,surfaces:true}}){
const counts={paths:0,widthEstimated:0,trees:0,treesEstimated:0,treesSource:0,objects:0,surfaces:0,symbolic:0,skipped:0};const materials=new Map();const mat=(color)=>{if(!materials.has(color))materials.set(color,new T.MeshStandardMaterial({color,side:T.DoubleSide}));return materials.get(color);};
const pos=([x,y],h=.18)=>[x-side/2,elevation(x,y)+h,side/2-y];
function lines(coords,color){let added=false;for(let i=1;i<coords.length;i++){const c=clipSegment(xy(coords[i-1]),xy(coords[i]),side);if(!c)continue;added=true;const points=sampledSegment(...c).map(p=>new T.Vector3(...pos(p,.25)));scene.add(new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color})));}return added;}
function marker(p,kind,tags={}){const q=xy(p);if(q.some(v=>v<0||v>side))return false;const origin=pos(q,0);const mesh=(g,color,y)=>{const m=new T.Mesh(g,mat(color));m.position.set(origin[0],origin[1]+y,origin[2]);scene.add(m);};if(kind==='tree'){const {h,d,estimated}=treeDimensions(tags,treeHeight,treeCrown),r=Math.min(d/2,h*.4);counts[estimated?'treesEstimated':'treesSource']++;mesh(new T.CylinderGeometry(.13,.18,h*.5,6),0x70543a,h*.25);const crown=new T.SphereGeometry(1,8,6);crown.scale(d/2,r,d/2);mesh(crown,0x46764c,h-r);}else if(kind==='street_lamp'){mesh(new T.CylinderGeometry(.08,.1,3,6),0x687e87,1.5);mesh(new T.SphereGeometry(.25,6,4),0xf3e5b5,3);}else if(kind==='waste_basket'){mesh(new T.CylinderGeometry(.25,.22,.7,8),0x687e87,.35);}else if(kind==='bicycle_parking'){mesh(new T.TorusGeometry(.5,.06,4,8,Math.PI),0x687e87,.1);}else if(kind==='bench'){mesh(new T.BoxGeometry(1.8,.25,.6),0x815f43,.5);}else if(kind==='fountain'){mesh(new T.CylinderGeometry(1,1,.25,12),0x66adc3,.18);}else{mesh(new T.BoxGeometry(.6,.8,.6),0x687e87,.4);}return true;}
for(const f of features){const p=f.properties||{},g=f.geometry;if(!g||p.tainted)continue;if(['construction','proposed'].includes(p.highway)){counts.skipped++;continue;}if((p.bridge&&p.bridge!=='no')||(p.tunnel&&p.tunnel!=='no')){counts.skipped++;continue;}if(layers.paths&&p.highway&&['LineString','MultiLineString'].includes(g.type)){let added=false;const walking=['footway','path','pedestrian','steps','cycleway'].includes(p.highway),known=sourceSize(p.width),width=known??sourceSize(walking?pathWidth:roadWidth)??(walking?2:6);for(const l of g.type==='LineString'?[g.coordinates]:g.coordinates){const v=drapePolygon&&drapePolyline?exactRibbonVertices(l.map(xy),width,side,drapePolygon,drapePolyline,walking?curbHeight:0):ribbonVertices(l.map(xy),width,side,elevation,walking?curbHeight:0);if(v.length){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(v,3));geometry.computeVertexNormals();scene.add(new T.Mesh(geometry,mat(walking?0xd5ba89:0x858c90)));added=true;}}if(added){counts.paths++;if(known===null){counts.widthEstimated++;counts.symbolic++;}}}
if((layers.objects&&p.barrier||layers.trees&&p.natural==='tree_row')&&g.type==='LineString'){if(lines(g.coordinates,0x55764c)){counts.objects++;counts.symbolic++;}}if(g.type==='Point'){if(layers.trees&&p.natural==='tree'){if(marker(g.coordinates,'tree',p)){counts.trees++;counts.symbolic++;}}else if(layers.objects&&(['bench','waste_basket','fountain','bicycle_parking','drinking_water'].includes(p.amenity)||p.highway==='street_lamp')){if(marker(g.coordinates,p.amenity||p.highway,p)){counts.objects++;counts.symbolic++;}}}
if(layers.surfaces&&['river','stream','canal','drain','ditch'].includes(p.waterway)&&g.type==='LineString'){if(lines(g.coordinates,0x72a9bd)){counts.surfaces++;counts.symbolic++;}}const road=!!p['area:highway']||(p.highway&&p.area==='yes')||p.amenity==='parking';const green=['wood','grassland','scrub'].includes(p.natural)||['forest','grass','meadow','recreation_ground'].includes(p.landuse)||['park','garden'].includes(p.leisure),water=p.natural==='water'||p.water||['reservoir','basin'].includes(p.landuse),play=['playground','pitch'].includes(p.leisure);if(!layers.surfaces||!(green||water||play||road))continue;
for(const poly of g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[]){if(!validPolygon(poly)){counts.skipped++;continue;}const rings=poly.map(r=>r.map(xy));if(drapePolygon){const verts=drapePolygon(rings,road?.025:play?.015:water?.01:.005);if(verts.length){const geometry=new T.BufferGeometry();geometry.setAttribute("position",new T.Float32BufferAttribute(verts,3));geometry.computeVertexNormals();scene.add(new T.Mesh(geometry,mat(water?0x78acbe:play?0xc9b88f:road?0xb3ada1:0x83a77a)));counts.surfaces++;}continue;}if(rings.some(r=>r.some(q=>q.some(v=>v<0||v>side)))){for(const r of poly)lines(r,water?0x72a9bd:0x729666);continue;}const contour=rings[0].slice(0,-1).map(q=>new T.Vector2(...q)),holes=rings.slice(1).map(r=>r.slice(0,-1).map(q=>new T.Vector2(...q))),all=[...contour,...holes.flat()];const faces=T.ShapeUtils.triangulateShape(contour,holes),verts=[];function tri(a,b,c,depth=0){if(depth<8&&Math.max(a.distanceTo(b),b.distanceTo(c),c.distanceTo(a))>Math.max(8,side/100)){const ab=a.clone().add(b).multiplyScalar(.5),bc=b.clone().add(c).multiplyScalar(.5),ca=c.clone().add(a).multiplyScalar(.5);tri(a,ab,ca,depth+1);tri(ab,b,bc,depth+1);tri(ca,bc,c,depth+1);tri(ab,bc,ca,depth+1);}else for(const q of [a,b,c])verts.push(...pos([q.x,q.y],.005));}for(const face of faces)tri(...face.map(i=>all[i]));if(verts.length){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(verts,3));geometry.computeVertexNormals();scene.add(new T.Mesh(geometry,mat(water?0x78acbe:play?0xc9b88f:road?0xb3ada1:0x83a77a)));counts.surfaces++;}}
}return counts;}



